def transform(grid):
    # Crop each non-background rectangle and superimpose them.
    bg = grid[0][0]
    rows, cols = len(grid), len(grid[0])
    blocks = []
    used = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg or (r, c) in used:
                continue
            if any((rr, cc) in used for rr in range(r+1) for cc in range(c+1)):
                continue
            # A rectangle begins where both cells above and left are background.
            if (r > 0 and grid[r-1][c] != bg) or (c > 0 and grid[r][c-1] != bg):
                continue
            hh = 0
            while r+hh < rows and grid[r+hh][c] != bg:
                hh += 1
            ww = 0
            while c+ww < cols and grid[r][c+ww] != bg:
                ww += 1
            blocks.append((r, c, hh, ww))
            for i in range(hh):
                for j in range(ww):
                    used.add((r+i, c+j))
    hh, ww = blocks[0][2:]
    ans = [[bg]*ww for _ in range(hh)]
    for r, c, hh, ww in blocks:
        for i in range(hh):
            for j in range(ww):
                ans[i][j] = grid[r+i][c+j]
    return ans
