            if c and grid[r][c - 1] != bg:
                continue
            height = 1
            while r + height < len(grid) and grid[r + height][c] != bg:
                height += 1
            width = 1
            while c + width < len(row) and grid[r][c + width] != bg:
                width += 1
            rects.append((r, c, height, width))
