    result = [line[c:c + width] for line in grid[r:r + height]]
    # Every non-background rectangle contributes its cells at the same offsets.
    for r, c, height, width in rects[1:]:
        for i in range(height):
            for j in range(width):
                result[i][j] = grid[r + i][c + j]
